CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, display_name text NOT NULL, verified_at timestamptz, is_admin boolean NOT NULL DEFAULT false, suspended boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS auth_tokens(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose text NOT NULL CHECK(purpose IN ('verify','reset')), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY, name text NOT NULL, owner_id uuid NOT NULL REFERENCES users(id), revision bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','admin','editor','viewer')), PRIMARY KEY(workspace_id,user_id));
CREATE INDEX IF NOT EXISTS memberships_user ON memberships(user_id);
CREATE TABLE IF NOT EXISTS invitations(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','editor','viewer')), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, accepted_at timestamptz);
CREATE TABLE IF NOT EXISTS entities(workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE, id uuid, kind text NOT NULL CHECK(kind IN ('collection','request','environment')), version integer NOT NULL CHECK(version>0), data jsonb NOT NULL, deleted boolean NOT NULL DEFAULT false, updated_by uuid REFERENCES users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,id));
CREATE TABLE IF NOT EXISTS changes(workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE, revision bigint, entity_id uuid NOT NULL, version integer NOT NULL, data jsonb NOT NULL, kind text NOT NULL, deleted boolean NOT NULL, PRIMARY KEY(workspace_id,revision));
CREATE TABLE IF NOT EXISTS operations(workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE, operation_id uuid, user_id uuid REFERENCES users(id) ON DELETE SET NULL, request_hash text NOT NULL, response jsonb NOT NULL, PRIMARY KEY(workspace_id,operation_id));
CREATE TABLE IF NOT EXISTS comments(id uuid PRIMARY KEY, workspace_id uuid NOT NULL, entity_id uuid NOT NULL, author_id uuid REFERENCES users(id) ON DELETE SET NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,entity_id) REFERENCES entities(workspace_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS comments_entity ON comments(workspace_id,entity_id);
CREATE TABLE IF NOT EXISTS plans(id text PRIMARY KEY, name text NOT NULL, active boolean NOT NULL DEFAULT true, max_members integer NOT NULL CHECK(max_members>0), price_minor integer CHECK(price_minor>=0), currency text NOT NULL DEFAULT 'TND');
INSERT INTO plans(id,name,max_members) VALUES('free','Free',1),('pro','Pro',1),('team','Team',25) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS subscriptions(workspace_id uuid PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE, plan_id text NOT NULL REFERENCES plans(id), status text NOT NULL CHECK(status IN ('active','cancelled')), expires_at timestamptz NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, submitted_by uuid REFERENCES users(id) ON DELETE SET NULL, plan_id text NOT NULL REFERENCES plans(id), reference text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), reviewed_by uuid REFERENCES users(id) ON DELETE SET NULL, review_note text, created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
CREATE INDEX IF NOT EXISTS payments_status ON payments(status,created_at);
CREATE TABLE IF NOT EXISTS audit_log(id uuid PRIMARY KEY, actor_id uuid REFERENCES users(id) ON DELETE SET NULL, workspace_id uuid REFERENCES workspaces(id) ON DELETE SET NULL, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_workspace ON audit_log(workspace_id,created_at);
CREATE TABLE IF NOT EXISTS configuration(key text PRIMARY KEY, value text NOT NULL);
INSERT INTO configuration VALUES('payment_contact','56668672') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS email_outbox(id uuid PRIMARY KEY, recipient text NOT NULL, subject text NOT NULL, body text NOT NULL, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
